
const mongoose = require("mongoose");

const contactPhoneVerificationChallengeSchema = new mongoose.Schema(
  {
    firebaseUid: {
      type: String,
      required: true,
      unique: true,
      index: true,
    },

    phoneNumber: {
      type: String,
      required: true,
    },

    // MSG91 Widget contact verification uses SMS.
    channel: {
      type: String,
      enum: ["sms"],
      default: "sms",
      required: true,
    },

    // Generated by our backend for each verification session.
    sessionId: {
      type: String,
      required: true,
      unique: true,
    },

    attempts: {
      type: Number,
      default: 0,
    },

    expiresAt: {
      type: Date,
      required: true,
    },

    // SHA-256 hash of the MSG91 access token.
    // Never store the original access token.
    accessTokenHash: {
      type: String,
      default: undefined,
    },

    verifiedAt: {
      type: Date,
      default: null,
    },

    consumedAt: {
      type: Date,
      default: null,
    },
  },
  { timestamps: true }
);

// Prevent reuse of the same verified access token.
contactPhoneVerificationChallengeSchema.index(
  { accessTokenHash: 1 },
  {
    unique: true,
    partialFilterExpression: {
      accessTokenHash: { $type: "string" },
    },
  }
);

module.exports = mongoose.models.ContactPhoneVerificationChallenge ||
  mongoose.model(
    "ContactPhoneVerificationChallenge",
    contactPhoneVerificationChallengeSchema
  );
